"use strict";
/* ---------- Intro to Cybersecurity : 29 leçons pour 7 modules (183 challenges sur le site, tous lus) ----------
   Contenu récupéré le 18 novembre 2026 sur https://pwn.college/intro-to-cybersecurity/ (lecture
   connectée) : 183 défis sur 183 lus, aucun verrouillé. Les « lectures » de chaque module sont des
   vidéos YouTube, non transcrites : ces leçons travaillent à partir des sujets des défis.
   Les défis Secure Chat 1–5 (module Integrated Security) n’ont AUCUN texte de description sur le
   site : ils sont signalés comme non disponibles dans l’écran du dojo, sans contenu inventé.
   Leçons ORIGINALES écrites en français pour Nexus Guardian, adaptées des sujets des modules —
   aucun texte du site n’est copié, aucun mot de passe ni flag de challenge n’est reproduit.
   Les gros modules sont découpés : Web Security en 5 leçons, Intercepting Communication en 5,
   Cryptography en 6, Reverse Engineering en 5, Binary Exploitation en 4, Access Control en 3,
   Integrated Security en 1 (plus la carte Secure Chat). */
var DOJO_ICS_LESSONS = [
  { id:"ICS-01", mod:"Web Security", t:"Sortir du dossier : traversée de chemin et injection de commande", sub:"Deux failles nées du même écart : ce que le développeur imagine, et ce que l’entrée peut vraiment contenir.",
    read:["Un serveur web sert des fichiers depuis un dossier prévu — disons /challenge/files. La traversée de chemin (path traversal) exploite un écart simple : le développeur imagine que le nom demandé désigne un fichier de ce dossier, mais un chemin peut contenir des séquences qui remontent d’un niveau, encore et encore, jusqu’à n’importe quel fichier du système. Même quand un filtre tente de bloquer ces séquences, une mauvaise compréhension des chemins piégeux laisse souvent une porte ouverte.",
      "L’injection de commande (CMDi) est la cousine côté shell : le serveur construit une commande système en y collant une entrée de l’utilisateur — par exemple un mot à afficher. Si l’entrée contient les caractères spéciaux du shell, elle peut chaîner une deuxième commande à la première. Les variantes du module jouent sur les filtres : interdire le point-virgule force à trouver un autre séparateur ; injecter entre guillemets oblige à refermer proprement la construction ; et l’injection aveugle ne renvoie aucune sortie — il faut alors faire parler le serveur autrement, par ses effets observables.",
      "Le point commun des deux familles : le programme mélange des données venues de l’extérieur avec un langage — chemins du système de fichiers d’un côté, langage du shell de l’autre — sans séparer ce qui est instruction de ce qui est donnée."],
    term:"GET /fichier?nom=rapport.txt → le serveur lit dans son dossier prévu\n<span class=\"tdim\">Question à se poser devant chaque entrée : que se passe-t-il si elle contient des caractères spéciaux du langage cible ?</span>",
    ex:{ type:"qcm", q:"Quelle est la cause commune de la traversée de chemin et de l’injection de commande ?",
      opts:["Le serveur est écrit en Python", "Le programme mélange une entrée extérieure avec un langage (chemins ou shell) sans séparer données et instructions", "Les mots de passe des utilisateurs sont trop courts"], ok:1 },
    why:"Dans les deux cas, l’attaquant ne casse pas le programme : il lui parle dans son propre langage, un cran plus loin que prévu. Côté défense, la parade est la même : valider strictement l’entrée, et ne jamais construire de chemins ni de commandes par collage de chaînes." },
  { id:"ICS-02", mod:"Web Security", t:"Contourner l’authentification : ce que le développeur n’avait pas prévu", sub:"Tu contrôles chaque octet de la requête — y compris ceux que l’application croyait choisir elle-même.",
    read:["Une application web ne voit de toi que ce que ta requête contient : paramètres d’URL, en-têtes, cookies. Le contournement d’authentification naît d’un écart entre ce que le développeur attend — « les paramètres ne sont définis que par mon application » — et la réalité : un attaquant fabrique n’importe quelle requête, avec n’importe quels paramètres et en-têtes, sans passer par l’interface prévue.",
      "La logique du programme peut sembler correcte ligne par ligne, et pourtant reposer sur une hypothèse fausse : qu’un paramètre absent restera absent, qu’un en-tête ne peut venir que du navigateur officiel, qu’un rôle annoncé par le client est digne de confiance. Le module enchaîne deux contournements de difficulté croissante, où il faut deviner quelle hypothèse le développeur a faite — et la contredire poliment, en HTTP.",
      "Côté défense, la leçon est limpide : tout ce qui vient de la requête est suspect, y compris ce que ton propre formulaire n’enverrait jamais. L’autorisation se décide côté serveur, à partir d’informations que le client ne peut pas fabriquer."],
    ex:{ type:"qcm", q:"Pourquoi un attaquant peut-il envoyer des paramètres que l’application n’a jamais prévus ?",
      opts:["Parce qu’il connaît le mot de passe admin", "Parce qu’il fabrique lui-même ses requêtes HTTP, sans passer par l’interface de l’application", "Parce que le serveur accepte toutes les connexions"], ok:1 },
    why:"L’interface web n’est qu’une suggestion : le vrai contrat, c’est le protocole HTTP, et n’importe qui peut écrire une requête à la main — tu l’as fait dans Playing With Programs. Toute hypothèse du type « ce paramètre ne peut pas contenir ça » doit donc être vérifiée côté serveur, jamais supposée." },
  { id:"ICS-03", mod:"Web Security", t:"Injection SQL : parler à la base par-dessus l’épaule de l’application", sub:"La requête prévue, plus un morceau de la tienne : conditions ajoutées, tables surprises et réponses oui/non.",
    read:["Une application construit souvent ses requêtes SQL en y insérant des entrées utilisateur. L’injection SQL (SQLi) consiste à glisser dans cette entrée un morceau de SQL qui modifie la requête : ajouter une condition qui rend l’authentification toujours vraie, par exemple, pour se connecter sans mot de passe. Le point d’injection peut se trouver au milieu d’une requête : il faut alors garder l’ensemble syntaxiquement valide, la fin de la requête d’origine continuant après ton morceau.",
      "Le cran suivant enchaîne les requêtes pour interroger des tables et des champs que l’application n’utilise jamais — c’est ainsi que se produisent les grandes divulgations de données. Et quand le nom des tables est aléatoire, la base elle-même détient la carte : elle conserve son schéma dans des tables système (information_schema) que l’on peut interroger comme les autres.",
      "Reste le cas aveugle : aucune donnée ne ressort directement. Mais si l’application réagit différemment selon que la réponse est oui ou non — une redirection « succès » contre une redirection « échec » — chaque question fermée fait fuiter un bit d’information. Assez de questions patientes, et le secret se reconstruit bit par bit."],
    term:"Requête prévue : ... WHERE nom = ’ENTRÉE’\n<span class=\"tdim\">Si l’entrée contient des guillemets et du SQL, la frontière entre donnée et requête disparaît.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre la démarche d’une injection SQL aveugle :",
      items:["Trouver le point d’injection dans la requête", "Vérifier que l’application réagit différemment selon oui ou non", "Formuler une question fermée sur un seul bit du secret", "Répéter question par question jusqu’à reconstruire le secret"],
      disp:[1,3,0,2] },
    why:"L’injection aveugle transforme l’application en oracle : elle ne montre rien, mais elle répond. C’est un schéma général en sécurité — un canal d’un bit, répété assez de fois, devient un canal complet. Côté défense : requêtes paramétrées, qui séparent définitivement le code SQL des données." },
  { id:"ICS-04", mod:"Web Security", t:"XSS : du code à toi, exécuté chez la victime", sub:"Stocké ou réfléchi, le script injecté agit avec les droits de la session de la victime — cookies compris.",
    read:["Le cross-site scripting (XSS) injecte du code JavaScript dans une page que la victime consulte : le navigateur l’exécute alors comme s’il faisait partie du site, avec l’identité et la session de la victime. En XSS stocké, le code est enregistré par le site — un message de forum, par exemple — et servi à chaque visiteur. En XSS réfléchi, le code voyage dans l’URL et le site le renvoie aussitôt dans la page.",
      "Le contexte d’injection change tout : un script placé dans le corps de la page ne se ferme pas comme un script coincé dans une zone de texte — il faut d’abord sortir du contexte où l’on est enfermé avant de pouvoir agir. Les premiers défis du module valident l’injection par un simple alert affiché chez la victime simulée.",
      "Le vrai objectif vient ensuite : depuis le script injecté, utiliser fetch pour agir en tant que victime — lire un brouillon privé de l’administrateur, publier à sa place via un POST, ou exfiltrer son cookie de session vers un serveur que l’attaquant contrôle et où il écoute. Seule limite notable : un cookie marqué httponly échappe à la lecture JavaScript — mais pas aux requêtes faites avec la session."],
    term:"Le script injecté affiche « PWNED » chez la victime — la signature classique d’une injection réussie\n<span class=\"tdim\">Stocké : le piège attend ses victimes sur le site · Réfléchi : le piège voyage dans le lien.</span>",
    ex:{ type:"qcm", q:"Pourquoi le XSS est-il si puissant alors qu’il ne touche « que » le navigateur de la victime ?",
      opts:["Parce qu’il éteint le serveur", "Parce que le script injecté s’exécute avec la session de la victime : il peut lire ses pages et agir en son nom", "Parce qu’il vole le mot de passe de l’administrateur du serveur"], ok:1 },
    why:"Le navigateur ne distingue pas le code du site du code injecté : même origine, mêmes droits. Tout ce que la victime peut faire dans l’application, le script peut le tenter. Défenses : échapper les données affichées selon le contexte, et marquer les cookies de session httponly pour limiter le vol de session." },
  { id:"ICS-05", mod:"Web Security", t:"CSRF : la requête que la victime n’a jamais voulu envoyer", sub:"Le navigateur joint les cookies tout seul — une page malveillante peut donc commander à la place de la victime.",
    read:["Le cross-site request forgery (CSRF) retourne le problème : pas besoin d’injecter du code dans le site cible. Quand la victime, connectée au site, visite une page malveillante, cette page peut déclencher une requête vers le site cible — et le navigateur y joint automatiquement les cookies de session. Le site reçoit une requête authentifiée… que la victime n’a jamais décidée.",
      "La politique de même origine (same-origin policy) empêche le JavaScript d’une origine de lire les réponses d’une autre, mais elle n’empêche pas d’envoyer : un simple GET peut être déclenché par une redirection ou le chargement d’une ressource, et un POST peut partir d’un formulaire HTML soumis par script — la victime n’a même pas besoin de cliquer.",
      "Le module combine ensuite les familles : un CSRF qui déclenche un XSS sur le site cible, puis la chaîne complète — CSRF vers XSS vers fuite de cookie. Quand le cookie est httponly, la parade de l’attaquant est de rester dans la page : fetch des pages de la même origine et lecture de leur contenu, toujours avec la session de la victime."],
    ex:{ type:"order", q:"Remets dans l’ordre le déroulement d’une attaque CSRF :",
      items:["La victime se connecte au site cible (session active)", "La victime visite la page malveillante de l’attaquant", "La page déclenche une requête vers le site cible", "Le navigateur joint automatiquement les cookies de session", "Le site cible exécute l’action comme si la victime l’avait demandée"],
      disp:[2,0,4,1,3] },
    why:"Le CSRF n’exploite ni le code du site ni celui du navigateur, mais la confiance entre les deux : l’authentification automatique par cookies. La défense classique est un jeton anti-CSRF imprévisible, exigé pour toute action qui change l’état — une page étrangère peut déclencher une requête, mais elle ne peut pas deviner le jeton." },
  { id:"ICS-06", mod:"Intercepting Communication", t:"Parler en réseau : netcat dans les deux sens", sub:"Se connecter, envoyer, fermer proprement, écouter : les quatre gestes de base de la conversation réseau.",
    read:["Ce module repart de zéro, côté réseau : deux hôtes, des adresses comme 10.0.0.1 et 10.0.0.2, et un port — 31337 dans les défis. L’outil de base est netcat (nc) : pour se connecter à un service distant, on lui donne l’adresse et le port ; ce qu’on tape part sur la connexion, ce que l’autre répond s’affiche. La connexion est bidirectionnelle : les deux côtés peuvent parler.",
      "Trois subtilités structurent les premiers défis. Envoyer : le terminal met le texte en tampon jusqu’à la touche Entrée — un seul paquet part alors, pas un par caractère. Fermer : mettre fin à son côté de la conversation (Ctrl-D, fin de fichier) ne va pas de soi — par défaut, nc ne ferme pas après la fin de l’entrée ; une option de sa page de manuel règle ce comportement. Écouter : le même outil, en mode écoute, attend une connexion entrante sur un port — c’est ainsi qu’on monte un serveur minimal, et plus tard qu’on reçoit des données exfiltrées."],
    term:"nc 10.0.0.2 31337 → se connecter · nc en mode écoute → attendre sur un port\n<span class=\"tdim\">Ctrl-C : tout couper · Ctrl-D : signaler la fin de ton entrée.</span>",
    ex:{ type:"qcm", q:"Pourquoi le message tapé dans nc ne part-il qu’au moment où l’on appuie sur Entrée ?",
      opts:["Parce que le réseau est lent", "Parce que le terminal met la saisie en tampon et la transmet par ligne complète", "Parce que nc chiffre le message avant l’envoi"], ok:1 },
    why:"Ce tampon de ligne est celui du terminal, pas du réseau : il rappelle que ce que tu vois n’est pas ce qui voyage. Comprendre à quel moment les données partent vraiment — et sous quelle forme — est le réflexe de base de tout le module, du scan à l’interception." },
  { id:"ICS-07", mod:"Intercepting Communication", t:"Scanner et écouter : cartographier, puis regarder passer", sub:"Ping sur 256 hôtes, nmap sur 65 536, et Wireshark pour voir le trafic des autres.",
    read:["Avant d’intercepter, il faut savoir qui est là. Le scan consiste à sonder un réseau entier : sur un petit réseau de 256 adresses, une boucle qui ping chaque hôte suffit. Sur un réseau de 65 536 adresses, à raison de dix sondes par seconde, il faudrait plus d’une heure — c’est le moment de passer à nmap, l’outil conçu pour ça, en réglant la vitesse d’envoi et en désactivant la résolution DNS qui ralentit tout.",
      "Deuxième posture : écouter. Un trafic déjà présent sur le réseau peut être capturé et lu avec Wireshark, lancé avec les privilèges nécessaires. Le module monte en puissance : observer un trafic lent, puis voler le cookie d’un administrateur qui transite en clair — la démonstration éclatante que HTTP sans chiffrement expose tout, identifiants de session compris.",
      "Scan et écoute sont les deux faces de la connaissance réseau : le scan cartographie ce qui existe, l’écoute révèle ce qui s’y dit. En défense, ce sont aussi deux bruits caractéristiques à détecter : un hôte qui sonde tout le réseau, et une interface qui capture ce qui ne lui est pas destiné."],
    ex:{ type:"qcm", q:"Pourquoi passer d’une boucle de ping à nmap quand le réseau grandit ?",
      opts:["Parce que ping ne fonctionne plus au-delà de 256 hôtes", "Parce qu’à débit constant, le temps explose avec le nombre d’adresses : nmap parallélise et règle finement l’envoi", "Parce que nmap est plus discret dans les journaux"], ok:1 },
    why:"65 536 hôtes à 10 sondes par seconde, c’est plus de 6 500 secondes : l’échelle change l’outil. C’est une leçon générale d’opérations : une technique artisanale correcte sur un petit périmètre devient inutilisable à grande échelle — d’où les outils spécialisés, et leurs réglages." },
  { id:"ICS-08", mod:"Intercepting Communication", t:"Configurer, filtrer, saturer : routage, pare-feu et déni de service", sub:"Faire communiquer deux hôtes, décider qui passe avec iptables, puis épuiser les ressources de l’autre.",
    read:["Pour que deux hôtes se parlent, il ne suffit pas de brancher : les interfaces doivent être configurées et actives, avec les bonnes adresses. Le module fait communiquer un hôte vers un autre en rappelant les couches : Ethernet livre sur le réseau local (couche 2), IP achemine entre réseaux (couche 3) — et seuls les paquets conformes à ce que l’interface attend sont acceptés.",
      "Le pare-feu filtre ce trafic selon des règles ordonnées — avec iptables, l’ordre compte : la première règle qui correspond décide. Les défis montent en précision : bloquer un port vers un hôte, bloquer ce même port pour une seule source tout en autorisant une autre, puis l’inverse — un trafic sortant bloqué qu’il faut d’abord autoriser avant de pouvoir se connecter.",
      "Le déni de service (DoS), enfin, n’exploite aucune faille de code : il épuise une ressource. Ici, la file des connexions en attente d’un serveur ; puis, contre un serveur qui crée un processus par client, la ressource devient les processus eux-mêmes ; et quand chaque session est limitée à une seconde, il faut entretenir la saturation en continu plutôt que la déclencher une fois."],
    ex:{ type:"qcm", q:"Dans un pare-feu à règles ordonnées comme iptables, pourquoi l’ordre des règles est-il crucial ?",
      opts:["Parce que les règles sont relues dans le désordre", "Parce que la première règle qui correspond au paquet décide de son sort : une règle large placée trop tôt écrase les exceptions", "Parce qu’il faut une règle par port, dans l’ordre croissant"], ok:1 },
    why:"« Bloquer le port 31337 » puis « autoriser 10.0.0.2 » ne donne pas le même résultat selon l’ordre : si le blocage passe en premier, l’autorisation ne sera jamais atteinte. C’est la source classique des pare-feux qui « semblent corrects » et laissent tout passer — ou bloquent tout." },
  { id:"ICS-09", mod:"Intercepting Communication", t:"Fabriquer ses paquets : Ethernet, IP, TCP, UDP à la main", sub:"Sockets bruts et Scapy : remplir soi-même chaque champ d’en-tête, jusqu’à la poignée de main TCP.",
    read:["Jusqu’ici, les outils écrivaient les paquets pour toi. Ce bloc les fabrique à la main, couche par couche : une trame Ethernet avec un type personnalisé, un paquet IP avec un protocole inhabituel, un segment TCP dont chaque champ est choisi — ports source et destination, numéros de séquence et d’acquittement, et tous les drapeaux à la fois. L’outil de prédilection est Scapy, la bibliothèque Python qui construit, envoie et reçoit des paquets champ par champ.",
      "Le point d’orgue est la poignée de main TCP manuelle : envoyer le segment initial avec les valeurs imposées, recevoir la réponse du serveur, et répondre à son tour pour établir la connexion — les trois temps que nc et le navigateur font d’habitude sans te consulter.",
      "UDP offre le contraste parfait : pas de connexion, pas de poignée de main, un en-tête minimal — ports, longueur, somme de contrôle. On y envoie un premier message, puis on apprend à fixer son port source en liant la socket avant l’envoi : un détail qui deviendra central dans les défis d’usurpation qui suivent."],
    term:"Scapy : Ether() / IP() / TCP() — chaque couche s’empile comme une ligne de code\n<span class=\"tdim\">TCP : connexion, séquences, acquittements · UDP : quatre champs d’en-tête et aucun état.</span>",
    ex:{ type:"order", q:"Remets dans l’ordre la poignée de main TCP :",
      items:["Le client envoie SYN avec son numéro de séquence", "Le serveur répond SYN-ACK : sa séquence à lui, et l’acquittement de la tienne", "Le client envoie ACK : la connexion est établie", "Les données peuvent circuler dans les deux sens"],
      disp:[2,0,3,1] },
    why:"Faire la poignée de main à la main oblige à comprendre ce que les numéros de séquence protègent : ils prouvent que les deux côtés participent réellement à la conversation. C’est exactement ce qui rendra TCP plus dur à usurper qu’UDP dans la suite du module." },
  { id:"ICS-10", mod:"Intercepting Communication", t:"Usurper et intercepter : UDP spoofing, ARP et homme du milieu", sub:"L’adresse source n’est vérifiée nulle part : confusion, amplification, et le mensonge d’ARP qui met l’attaquant au milieu.",
    read:["UDP ne vérifie pas l’adresse source : un paquet peut prétendre venir d’un autre. Le module exploite cette confiance de plusieurs façons : confondre un service qui croit parler à un client fiable, amplifier un déni de service en réutilisant des mécanismes construits sur UDP, attaquer la résolution DNS dans la lignée de la vulnérabilité Kaminsky — où le port source aléatoire doit être deviné par force brute — et fabriquer de toutes pièces la réponse d’un serveur. UDP se forge facilement : aucun numéro de séquence ne protège la conversation.",
      "ARP, le protocole qui associe adresses IP et adresses Ethernet sur le réseau local, ne vérifie rien non plus : annoncer « telle adresse IP se trouve à telle adresse Ethernet » suffit à être cru. C’est la clé de l’interception : convaincre deux hôtes que l’attaquant est l’autre, et leur trafic transite par lui.",
      "L’homme du milieu (MITM) est l’aboutissement : placé entre deux hôtes qui se parlent, l’attaquant lit tout ce qui passe en clair — et peut, en principe, modifier. Les parades sont connues : le chiffrement de bout en bout (TLS) rend l’interception stérile, et la surveillance des incohérences ARP trahit la manœuvre."],
    ex:{ type:"qcm", q:"Pourquoi l’usurpation est-elle plus facile en UDP qu’en TCP ?",
      opts:["Parce qu’UDP est plus rapide", "Parce qu’UDP n’a ni connexion ni numéros de séquence : rien ne prouve que l’émetteur est bien celui qu’il prétend être", "Parce que les paquets UDP sont plus petits"], ok:1 },
    why:"TCP impose une poignée de main et des séquences : forger une réponse crédible exige de deviner des valeurs échangées entre les vrais correspondants. UDP supprime ces preuves — toute la sécurité repose alors sur l’application, et les défis montrent ce qui arrive quand elle coupe les coins ronds." },
  { id:"ICS-11", mod:"Cryptography", t:"XOR : le chiffrement qui s’annule lui-même", sub:"Bit à bit, sans retenue : chiffrer et déchiffrer sont la même opération — et réutiliser la clé casse tout.",
    read:["Le XOR (ou exclusif) compare deux bits : 1 s’ils diffèrent, 0 sinon. Appliqué à des octets, il a une propriété précieuse : il est son propre inverse. 5 XOR 9 = 12, et 12 XOR 9 = 5. Contrairement à l’addition, il n’y a ni retenue ni débordement : chaque bit est indépendant. Les premiers défis s’entraînent : XORer des nombres, des valeurs hexadécimales, puis du texte — un caractère ASCII n’est qu’un nombre, et « A » (0x41) XOR 0x01 donne 0x40, le caractère « @ ».",
      "Chiffrer un message entier se fait octet par octet contre une clé, avec des outils comme strxor de PyCryptodome — en prenant garde aux pièges des chaînes de caractères contre les octets bruts. Avec une clé aussi longue que le message, vraiment aléatoire et utilisée une seule fois, on obtient le one-time pad : le chiffrement théoriquement parfait. Mais il ne protège que la confidentialité : connaître un clair et son chiffré révèle la clé, et permet d’altérer le message en transit de façon ciblée.",
      "Le pire arrive quand la clé se réutilise — le many-time pad. XORer deux chiffrés obtenus avec la même clé élimine la clé et laisse le XOR des deux clairs, que l’analyse finit par démêler. La clé à usage unique n’est pas un conseil de prudence : c’est la condition même de la sécurité."],
    term:"5 ^ 9 = 12 · 12 ^ 9 = 5 — le même geste chiffre et déchiffre\n<span class=\"tdim\">One-time pad : clé aussi longue que le message, aléatoire, jamais réutilisée.</span>",
    ex:{ type:"qcm", q:"Qu’est-ce qui rend le one-time pad incassable, et son cousin réutilisé fragile ?",
      opts:["La longueur de la clé ne compte pas, seul l’algorithme compte", "Une clé aléatoire aussi longue que le message et utilisée une seule fois ne laisse aucune prise ; réutilisée, elle s’élimine par XOR entre chiffrés", "Le one-time pad utilise des ordinateurs plus rapides"], ok:1 },
    why:"Avec une clé à usage unique, chaque chiffré possible correspond à un clair possible : aucune information ne filtre. Dès la deuxième utilisation, les chiffrés se combinent et la clé disparaît de l’équation — ne reste que la relation entre les messages, que l’attaquant exploite." },
  { id:"ICS-12", mod:"Cryptography", t:"AES-ECB : le codebook que l’attaquant construit lui-même", sub:"Même bloc de clair, même bloc de chiffré : l’attaque à clair choisi transforme le serveur en dictionnaire.",
    read:["AES chiffre par blocs de 16 octets. Le mode ECB, le plus simple, traite chaque bloc indépendamment : le même bloc de clair donne toujours le même bloc de chiffré, sous la même clé. Cette régularité est une faille : les motifs du clair transparaissent dans le chiffré.",
      "L’attaque à clair choisi (CPA) exploite un service qui chiffre des données que tu contrôles, mélangées à un secret : tu fais chiffrer des blocs de ton choix, tu construis un dictionnaire — un codebook — associant chaque chiffré obtenu au clair qui l’a produit, puis tu reconnais les blocs du secret quand ils apparaissent. Les variantes ajoutent les difficultés une à une : passer par une application web, décoder du base64, isoler la fin du secret dans son propre bloc en ajustant la longueur de tes données, octet par octet.",
      "Le boss du bloc ajoute un préfixe avant le secret : il faut préfixer tes propres données pour pousser la fin du secret dans un bloc neuf et l’isoler, bloc par bloc, en tenant compte du rembourrage PKCS7 — quand le clair remplit exactement un bloc, un bloc entier de rembourrage s’ajoute. La parade, elle, tient en un mot : ne jamais utiliser ECB."],
    ex:{ type:"qcm", q:"Quelle propriété d’ECB rend l’attaque par codebook possible ?",
      opts:["ECB chiffre lentement", "ECB produit toujours le même chiffré pour le même bloc de clair sous la même clé : on peut donc reconnaître les blocs", "ECB utilise des clés trop courtes"], ok:1 },
    why:"Un mode de chiffrement ne doit pas seulement cacher le contenu : il doit cacher les répétitions. ECB échoue à ce test élémentaire — deux blocs identiques se voient. Les modes sérieux mélangent chaque bloc au précédent ou à un compteur, précisément pour briser cette correspondance." },
  { id:"ICS-13", mod:"Cryptography", t:"AES-CBC et l’oracle de rembourrage", sub:"Chaîner les blocs protège mieux — jusqu’à ce qu’un message d’erreur sur le rembourrage dise tout.",
    read:["Le mode CBC corrige ECB : chaque bloc de clair est XORé avec le chiffré du bloc précédent avant chiffrement, et le premier bloc utilise un vecteur d’initialisation (IV) aléatoire, transmis en préfixe. Les répétitions disparaissent, le chiffrement devient séquentiel — mais l’intégrité n’est toujours pas là : XORer une valeur choisie dans le chiffré du bloc N−1 modifie de façon prévisible le clair du bloc N, au prix de corrompre le bloc N−1 ; altérer l’IV, lui, retouche le premier bloc sans rien corrompre.",
      "Le rembourrage PKCS7 complète le dernier bloc : N octets de valeur N. Si le déchiffrement signale « rembourrage invalide » différemment d’un succès, le serveur devient un oracle : en modifiant le chiffré et en observant l’erreur, on devine le dernier octet du clair — un rembourrage valide par hasard n’a qu’une chance sur 256 — puis l’avant-dernier, et ainsi de suite, bloc par bloc. Même les différences de temps de réponse peuvent servir d’oracle.",
      "Le plus surprenant : le même oracle permet aussi de chiffrer des données arbitraires, en remontant la chaîne à rebours. Découverte en 2002, cette famille d’attaques produit encore des vulnérabilités régulières. La vraie parade n’est pas de cacher l’erreur : c’est d’authentifier le chiffré, pour que toute altération soit rejetée avant même le déchiffrement."],
    ex:{ type:"order", q:"Remets dans l’ordre l’attaque par oracle de rembourrage sur un bloc :",
      items:["Modifier le chiffré du bloc précédent et soumettre au serveur", "Observer si l’erreur de rembourrage disparaît", "En déduire la valeur du dernier octet du clair", "Passer à l’octet précédent, et répéter jusqu’au bloc entier"],
      disp:[2,0,3,1] },
    why:"L’oracle transforme un détail d’implémentation — un message d’erreur trop bavard — en machine à déchiffrer. La leçon dépasse la crypto : en sécurité, toute différence observable entre « presque bon » et « faux » est un canal d’information, et les canaux d’un bit finissent toujours par tout laisser passer." },
  { id:"ICS-14", mod:"Cryptography", t:"Diffie-Hellman : un secret partagé fabriqué en public", sub:"Deux secrets qui ne voyagent jamais, un secret commun que l’écoute ne peut pas reconstruire.",
    read:["Problème : deux correspondants veulent une clé commune, mais tout ce qu’ils s’échangent peut être écouté. L’échange de clés Diffie-Hellman le résout avec de l’arithmétique modulaire : ils conviennent publiquement d’un grand nombre premier p et d’une base g. Chacun choisit un secret — a pour l’un, b pour l’autre — et publie g^a mod p et g^b mod p.",
      "Chacun élève alors la valeur publique de l’autre à la puissance de son propre secret : les deux calculs aboutissent au même nombre, g^(ab) mod p — le secret partagé, utilisable comme clé symétrique. C’est le deuxième défi du bloc : brancher ce secret sur un chiffrement symétrique pour obtenir un premier cryptosystème qui ressemble à un vrai.",
      "Pourquoi l’espion ne peut-il pas faire pareil ? Retrouver a depuis g^a mod p — le logarithme discret — est un calcul considéré comme infaisable aux tailles utilisées, alors que l’exponentiation, elle, est rapide. L’asymétrie entre faire et défaire est le moteur de toute la cryptographie à clé publique. Deux ombres au tableau : des paramètres mal choisis affaiblissent l’édifice, et un ordinateur quantique assez grand résoudrait le logarithme discret — d’où les premiers standardisés et la migration post-quantique en cours."],
    ex:{ type:"qcm", q:"Dans Diffie-Hellman, qu’est-ce qui ne voyage jamais sur le réseau ?",
      opts:["Le nombre premier p et la base g", "Les secrets a et b de chacun : seuls leurs résultats publics g^a et g^b mod p s’échangent", "Le secret partagé, qui est envoyé chiffré"], ok:1 },
    why:"Tout le génie du protocole tient là : le secret partagé n’est jamais transmis, il est reconstruit indépendamment des deux côtés. L’écoute voit p, g et les deux valeurs publiques — et reste bloquée devant le logarithme discret." },
  { id:"ICS-15", mod:"Cryptography", t:"RSA : signer avec le privé, vérifier avec le public", sub:"Factoriser pour déchiffrer, multiplier des signatures pour en forger : le théorème d’Euler à l’œuvre.",
    read:["RSA construit ses clés sur un produit de deux grands premiers, n = p × q. L’exposant public e — souvent 65537 — et l’exposant privé d sont inverses l’un de l’autre modulo (p−1)(q−1), grâce au théorème d’Euler : chiffrer, c’est élever à la puissance e modulo n ; déchiffrer, élever à la puissance d. Les premiers défis donnent toutes les clés pour vérifier la mécanique, puis seulement les facteurs de n : à toi de reconstruire d — car qui sait factoriser n sait tout déchiffrer, ce qui est aussi l’inquiétude historique de RSA, amplifiée par l’algorithme quantique de Shor.",
      "Le défi-réponse montre l’usage réel : prouver qu’on détient la clé privée sans la montrer, en traitant avec d un défi que seul d peut traiter. La signature inverse les rôles : on applique d à un condensat, et tout le monde vérifie avec e — la plume et l’encre, version mathématique.",
      "Mais RSA brut est malléable : (x^e) × (y^e) = (x×y)^e modulo n. Face à un service qui signe ce qu’on lui présente, cette propriété permet de combiner des signatures légitimes en une signature jamais émise — sur la commande qui libère le flag. C’est pourquoi les vrais systèmes signent des condensats formatés avec un rembourrage strict, jamais des nombres bruts."],
    ex:{ type:"qcm", q:"Pourquoi la connaissance des facteurs p et q de n détruit-elle RSA ?",
      opts:["Parce qu’elle donne l’adresse du serveur", "Parce qu’elle permet de recalculer l’exposant privé d, et donc de tout déchiffrer et signer", "Parce qu’elle efface les messages chiffrés"], ok:1 },
    why:"Toute la sécurité de RSA tient dans un sens unique : multiplier deux premiers est facile, factoriser leur produit est hors de portée. Une fois p et q connus, l’inverse de e se calcule et la clé privée est reconstruite — le coffre et sa clé ne font plus qu’un." },
  { id:"ICS-16", mod:"Cryptography", t:"Hash, preuve de travail et TLS : la confiance, bout à bout", sub:"Des empreintes à sens unique qui minent, et des certificats qui chaînent la confiance jusqu’à une racine.",
    read:["Une fonction de hachage transforme des données en empreinte de taille fixe, à sens unique et avec effet d’avalanche : changer un bit change tout. Sa hantise est la collision — deux données, une même empreinte. Les défis jouent à échelle réduite : trouver des données dont le SHA256 commence comme un secret donné sur quelques octets (collision partielle par force brute), puis la preuve de travail — des données dont le hash commence par des octets nuls, le mécanisme qui rend le minage coûteux et la triche chère.",
      "Le bloc Trust assemble tout le module dans TLS. Au cœur : les certificats, des cartes d’identité de clés publiques signées par une autorité. Les défis construisent la chaîne à la main : un certificat racine auto-signé et sa clé privée, la signature d’un certificat utilisateur, puis une poignée de main TLS simplifiée jouée côté serveur — échange Diffie-Hellman, dérivation d’une clé AES-128, présentation du certificat demandé signé par la racine, et signature de la poignée de main pour prouver qu’on détient bien la clé privée associée.",
      "C’est le modèle de confiance du web entier : tu ne connais pas le serveur, mais tu fais confiance à une racine, qui a signé pour lui. DH apporte le secret de session, AES le transporte, les signatures et certificats disent à qui tu parles."],
    ex:{ type:"order", q:"Remets dans l’ordre une poignée de main TLS simplifiée :",
      items:["Le client demande un canal sécurisé pour un nom précis", "Échange Diffie-Hellman : un secret de session naît des deux côtés", "Une clé AES-128 est dérivée du secret partagé", "Le serveur présente le certificat signé par la racine et signe la poignée de main", "Le canal chiffré s’ouvre, le certificat utilisateur transite dessus"],
      disp:[1,3,0,4,2] },
    why:"Chaque brique du module trouve sa place : sans DH, pas de secret de session ; sans certificat, pas d’identité ; sans signature de la poignée de main, rien ne prouve que le certificat présenté appartient à celui qui parle. TLS n’est pas un algorithme : c’est l’assemblage discipliné de tous les précédents." },
  { id:"ICS-17", mod:"Access Control", t:"DAC POSIX : qui possède, qui peut lire", sub:"Propriétaire, groupe, autres — neuf bits qui décident de presque tout sous Unix.",
    read:["Le contrôle d’accès discrétionnaire (DAC) est le modèle historique d’Unix : chaque fichier a un propriétaire, un groupe, et des permissions en trois trios — lecture, écriture, exécution — pour le propriétaire, le groupe, et tous les autres. Le propriétaire décide : c’est le sens de « discrétionnaire ». Les premiers niveaux du module sont des flags cachés derrière des combinaisons de permissions variées : le fichier t’appartient, mais ses permissions ne sont jamais celles qu’on attend.",
      "Lire une situation devient un exercice de précision : à qui appartient le fichier, à quel groupe, et quel trio s’applique à toi — sachant que le système teste dans l’ordre : si tu es le propriétaire, c’est ton trio qui décide, même s’il est plus restrictif que celui du groupe.",
      "Côté analyste SOC, ces neuf bits sont un langage quotidien : un fichier lisible par tous (« others ») avec des données sensibles, une permission d’écriture trop large sur un dossier système — la plupart des incidents d’accès commencent par un trio de trop."],
    term:"-rw-r-----  1  sara  soc  rapport.txt\n<span class=\"tdim\">Propriétaire : lecture-écriture · Groupe soc : lecture · Autres : rien du tout.</span>",
    ex:{ type:"qcm", q:"Tu es membre du groupe d’un fichier, mais aussi son propriétaire. Le trio propriétaire interdit la lecture, celui du groupe l’autorise. Peux-tu lire le fichier ?",
      opts:["Oui : le groupe autorise", "Non : le système applique le trio du propriétaire dès que tu es le propriétaire, sans regarder les autres", "Oui, mais en lecture seule"], ok:1 },
    why:"L’ordre d’évaluation est strict : propriétaire d’abord, groupe ensuite, autres enfin — le premier trio qui correspond à ton cas décide, même contre toi. C’est un piège classique d’administration, et l’un des premiers réflexes à vérifier quand « ça devrait marcher » mais que l’accès est refusé." },
  { id:"ICS-18", mod:"Access Control", t:"SETUID et groupes : emprunter une identité", sub:"Un bit qui fait tourner le programme avec les droits de son propriétaire — puissant, donc dangereux.",
    read:["Le bit SETUID change la règle du jeu : un programme marqué ainsi s’exécute avec les droits de son propriétaire — souvent root — plutôt que ceux de l’utilisateur qui le lance. C’est le mécanisme légitime derrière les rares commandes qui doivent toucher au système pour tout le monde ; c’est aussi, mal configuré, une autoroute d’élévation de privilèges. Les défis du module demandent d’expliquer son fonctionnement, puis ses interactions : que se passe-t-il quand un programme SETUID copie un fichier — à qui appartient la copie, avec quelles permissions ?",
      "Le groupe joue l’autre moitié du module : des flags possédés par un groupe différent du tien, des situations à plusieurs utilisateurs où le bon accès passe par l’appartenance au bon groupe — ou par l’utilisateur dont le trio, le groupe ou l’identité ouvre la porte.",
      "Pour un défenseur, l’inventaire des binaires SETUID d’un système est un contrôle de routine : chaque entrée doit être justifiée, car chacune est un emprunt d’identité que le système accorde à n’importe quel utilisateur local."],
    ex:{ type:"qcm", q:"Que fait concrètement le bit SETUID sur un programme ?",
      opts:["Il rend le programme plus rapide", "Il fait exécuter le programme avec les droits de son propriétaire, pas de celui qui le lance", "Il chiffre le programme pour le protéger"], ok:1 },
    why:"SETUID est un prêt d’identité automatique : indispensable pour quelques outils système, catastrophique sur un programme qui laisse l’utilisateur influencer ce qu’il fait. Tout le dojo Playing With Programs, avec ses programmes SUID détournés, montre l’envers de ce mécanisme." },
  { id:"ICS-19", mod:"Access Control", t:"MAC : quand le système décide, pas le propriétaire", sub:"Niveaux de sécurité et catégories : l’accès devient un calcul d’étiquettes — à automatiser quand il y en a 128.",
    read:["Le contrôle d’accès obligatoire (MAC) retire le pouvoir au propriétaire : une politique centrale étiquette chaque sujet et chaque objet — un niveau de sécurité (par exemple Confidentiel, Secret) et des catégories (des compartiments par thème). La règle de lecture compare les étiquettes : il faut un niveau au moins égal et toutes les catégories de l’objet. Personne ne peut « partager » au-delà de ce que les étiquettes autorisent.",
      "Le module commence par des questions uniques — avec puis sans catégories — puis par séries de cinq. L’étape finale change de nature : répondre à 20, puis 64, puis 128 questions en une seconde, avec des niveaux et catégories aléatoires. À ce rythme, il n’y a plus de réponse humaine possible : il faut automatiser — écrire le programme qui lit la question, applique la règle de comparaison des étiquettes et répond.",
      "C’est une leçon qui dépasse le MAC : beaucoup de métiers de la sécurité basculent ainsi de l’exécution manuelle à l’automatisation dès que le volume ou le délai l’exige — détection, réponse, et ici simple contrôle d’accès."],
    ex:{ type:"qcm", q:"Un sujet étiqueté « Secret, catégories {A} » peut-il lire un objet « Secret, catégories {A, B} » ?",
      opts:["Oui : le niveau est égal", "Non : il lui manque la catégorie B — la lecture exige toutes les catégories de l’objet", "Oui, si le propriétaire l’autorise"], ok:1 },
    why:"Le niveau seul ne suffit pas : les catégories compartimentent à niveau égal. Et dans le modèle MAC, l’autorisation du propriétaire ne change rien — c’est exactement ce qui distingue le MAC du DAC : la politique est obligatoire, pas discrétionnaire." },
  { id:"ICS-20", mod:"Reverse Engineering", t:"cIMG : nombres magiques et boutisme", sub:"Un format de fichier fictif à reconstruire de zéro — d’abord sa signature, puis le sens de ses octets.",
    read:["Le module entier tourne autour d’un format fictif, le Connor Image Format (cIMG), et du programme qui l’affiche : /challenge/cimg. Le rétro-ingénieur part de zéro connaissance et reconstruit la spécification en analysant le programme — avec un outil graphique d’analyse statique comme Ghidra et le débogueur gdb, plutôt qu’en lisant des listings bruts.",
      "Premier concept : le nombre magique. Les logiciels reconnaissent un format d’abord par son extension, puis par une signature en début de fichier — ELF commence par les octets \\x7fELF, par exemple. Le premier fichier cIMG à fabriquer doit porter le bon nombre magique, découvert en lisant le code du programme qui le vérifie. Le défi se répète ensuite en trois langages — Python, C, assembleur x86 — même concept, trois terrains.",
      "Deuxième concept : le boutisme (endianness). Quand le nombre magique est traité comme un nombre et non comme une suite d’octets, l’ordre de rangement compte : little-endian range l’octet de poids faible en premier. Écrire le fichier avec le mauvais boutisme, c’est écrire un nombre différent — le contrôle échoue sans explication visible."],
    term:"\\x7f E L F — les quatre premiers octets d’un exécutable Linux\n<span class=\"tdim\">Nombre magique : la signature qu’un format met en tête de chaque fichier.</span>",
    ex:{ type:"qcm", q:"Comment un programme distingue-t-il de façon fiable un fichier cIMG d’un fichier texte renommé ?",
      opts:["À l’extension du nom de fichier", "Au nombre magique : une signature fixe dans les premiers octets du fichier", "À la taille du fichier"], ok:1 },
    why:"L’extension est un nom, donc un mensonge possible ; le contenu ne ment pas. Tous les formats sérieux se signent dans leurs premiers octets, et la première chose qu’un rétro-ingénieur cherche dans un parseur, c’est cette comparaison — elle ouvre la porte à toute la structure." },
  { id:"ICS-21", mod:"Reverse Engineering", t:"Version, métadonnées et restrictions : le format grandit", sub:"Après la signature : un numéro de version, des dimensions — et des règles sur ce que les données peuvent contenir.",
    read:["Un format qui évolue doit dire à quelle version il parle : un champ version, rangé près du nombre magique, permet au programme de refuser ou d’interpréter correctement les fichiers d’autres générations. Fabriquer des données binaires devient un geste précis : écrire en mode binaire, utiliser les échappements hexadécimaux (\\x41 vaut « A »), ranger les entiers dans le bon boutisme avec le module struct de Python.",
      "Puis viennent les métadonnées : une image a des dimensions. Le fichier doit déclarer largeur et hauteur aux bons endroits, suivies des données elles-mêmes — métadonnées et données sont les deux moitiés de tout format. Le programme impose aussi des restrictions sur les entrées : certaines valeurs sont interdites ou bornées, et il faut lire le code pour découvrir lesquelles avant de construire un fichier accepté.",
      "Le module récompense alors le travail : le premier affichage d’une vraie cIMG, puis une nouvelle version du format, « bien plus proche de détrôner les vieux formats du web » — à toi de repérer ce qui a changé dans la spécification, toujours en lisant le programme."],
    ex:{ type:"qcm", q:"À quoi sert le champ version dans un format de fichier ?",
      opts:["À indiquer qui a créé le fichier", "À permettre au programme de savoir comment interpréter le fichier selon la génération du format", "À chiffrer les données"], ok:1 },
    why:"Sans version, un format ne peut pas évoluer : chaque changement casse les anciens fichiers ou les nouveaux lecteurs. Le champ version est la mémoire du format — et pour le rétro-ingénieur, comparer deux versions d’un parseur est l’un des moyens les plus rapides de comprendre ce qui compte vraiment dans la structure." },
  { id:"ICS-22", mod:"Reverse Engineering", t:"État interne et directives : lire ce que le programme retient", sub:"Le pipeline en cinq temps du rétro-ingénieur, et des fichiers qui donnent des ordres au lieu de données.",
    read:["Les défis d’état interne demandent plus que la structure du fichier : le programme entretient un état pendant le traitement, avec des exigences strictes sur ce qu’il doit devenir. Le module enseigne un pipeline en cinq temps : (1) comprendre l’état attendu grâce à l’analyse statique et au débogueur, en trouvant le point de décision ; (2) comprendre comment l’entrée produit les données intermédiaires — l’algorithme ; (3) inverser cet algorithme ; (4) appliquer l’inverse aux données douteuses ; (5) appliquer l’algorithme à l’état connu comme bon pour fabriquer l’entrée gagnante.",
      "Puis le format change de nature avec les directives : au lieu de décrire tous les pixels, le fichier donne des instructions au programme de rendu — comme les balises HTML ordonnent au navigateur. Chaque directive déclenche une action ; le format devient un petit langage.",
      "Cette montée en expressivité est le fil du reste du module : plus un format peut « dire » de choses, plus la frontière entre données et programme s’amincit — et c’est là que les vulnérabilités des parseurs naissent."],
    ex:{ type:"order", q:"Remets dans l’ordre le pipeline de rétro-ingénierie d’un état interne :",
      items:["Comprendre l’état interne attendu et trouver le point de décision", "Comprendre l’algorithme qui transforme l’entrée en données intermédiaires", "Inverser l’algorithme", "Appliquer l’inverse à l’état voulu pour obtenir l’entrée"],
      disp:[2,0,3,1] },
    why:"La méthode compte plus que le défi : on ne devine pas une entrée gagnante, on la calcule en remontant le programme à rebours. État attendu d’abord, algorithme ensuite, inversion enfin — c’est le schéma de résolution de la plupart des problèmes de rétro-ingénierie bien posés." },
  { id:"ICS-23", mod:"Reverse Engineering", t:"Directives Patch, sprites et optimisation", sub:"Dire la même image avec moins d’octets : patches, sprites réutilisables et édition hexadécimale.",
    read:["La directive Patch change l’économie du format : au lieu de redécrire chaque pixel, on corrige une image de base par endroits. Le programme refuse le flag si la solution gaspille trop d’octets — la taille devient un critère de réussite. Écrire ces fichiers à la main étant une fabrique d’erreurs, le module pousse à générer le fichier par un script Python, et à vérifier chaque hypothèse dans l’outil graphique et gdb plutôt qu’en devinant.",
      "Les sprites vont plus loin : définir un motif une fois, le ranger, et le réutiliser — stockage et récupération, puis sprites avancés où le compromis se négocie : plus de complexité dans le mécanisme contre des fichiers encore plus petits, à des tailles proches de l’optimal théorique.",
      "Deux défis changent d’outil : le flag lui-même est livré sous forme de cIMG, à retoucher dans un éditeur hexadécimal (hexedit) pour le rendre lisible ; et le défi « Extracting Knowledge » inverse les rôles — le programme de ce niveau ne peut pas donner le flag, mais un fichier fourni le contient : toute ta connaissance du format sert à l’en extraire."],
    ex:{ type:"qcm", q:"Pourquoi l’optimisation de taille fait-elle partie intégrante de ces défis ?",
      opts:["Parce que les gros fichiers sont interdits par le système", "Parce qu’atteindre la taille minimale prouve qu’on a compris les subtilités de la spécification, pas seulement son principe", "Parce que le programme est limité en mémoire"], ok:1 },
    why:"Une solution qui marche « à peu près » peut cacher une compréhension approximative. La solution optimale, elle, exige d’avoir compris chaque champ et chaque directive — c’est un test de compréhension déguisé en concours d’élégance, un classique des bons exercices de rétro-ingénierie." },
  { id:"ICS-24", mod:"Reverse Engineering", t:"Quand le format devient faille, et patcher le binaire", sub:"Des vulnérabilités dans le parseur, des animations piégées — puis modifier un programme sans son code source.",
    read:["À force d’ajouter des fonctionnalités, les pièces mobiles d’un format interagissent — et des vulnérabilités s’y glissent. Le module le fait constater : trouver et utiliser une faille du programme cIMG lui-même, puis une animation « dangereuse » où l’extensibilité des directives ouvre une brèche que le niveau suivant corrige, presque penaud, en redonnant le flag dans une cIMG animée.",
      "La fin du module change de métier : l’interopérabilité. Le code source d’un vieux jeu est perdu, son moteur graphique cIMG personnalisé aussi, et l’approximation fournie ne parle pas tout à fait le même dialecte. Il faut patcher le binaire — d’abord ses données, puis son code : de simples constantes utilisées par des instructions de comparaison, et enfin le flux de contrôle lui-même, des instructions légèrement plus piégeuses.",
      "Patcher un binaire est une compétence réelle et quotidienne : corriger un programme dont on n’a pas les sources, adapter un format, neutraliser un contrôle. C’est aussi la conclusion naturelle du module : tu ne lis plus seulement les programmes — tu les modifies."],
    ex:{ type:"qcm", q:"Pourquoi les vulnérabilités apparaissent-elles souvent quand un format gagne des fonctionnalités ?",
      opts:["Parce que les programmeurs deviennent négligents avec le temps", "Parce que chaque fonctionnalité interagit avec les autres : les combinaisons créent des cas que personne n’avait prévus ni testés", "Parce que les fichiers deviennent trop gros"], ok:1 },
    why:"Un parseur simple a peu de surfaces ; un parseur riche en directives, sprites et animations en a des dizaines, et leurs interactions explosent de façon combinatoire. Le travail du rétro-ingénieur — et de l’auditeur — est précisément de repérer ces interactions avant qu’elles ne servent quelqu’un d’autre." },
  { id:"ICS-25", mod:"Binary Exploitation", t:"Tes premiers débordements : précision et contrôle de variable", sub:"Écrire plus que la taille du tampon, mais pas n’importe comment : chaque octet de trop compte.",
    read:["Un débordement de tampon (buffer overflow) survient quand un programme écrit des données dans une zone mémoire sans vérifier qu’elles y tiennent : l’excédent écrase ce qui se trouve après — d’autres variables, puis les données de contrôle de la pile. Le premier défi est direct : déborder pour placer les bonnes conditions et obtenir le flag. Chaque défi du module existe en version easy — source fourni, sorties de débogage utiles — et hard : pas de source, informations à récupérer au débogueur, et tailles de tampons différentes qu’il faut rétro-ingénierer depuis le binaire.",
      "La précision devient vite la vraie leçon : déborder « beaucoup » corrompt les données de contrôle dans un état irrécupérable. Il faut écrire exactement assez — ni trop peu, ni trop.",
      "Le contrôle de variable affine encore : déborder juste ce qu’il faut pour écrire une valeur précise dans la variable qui conditionne la victoire. Les données sont binaires : on les construit avec Python, en respectant le boutisme, en évitant le saut de ligne parasite d’un echo sans -n, et on vérifie le résultat avec un affichage hexadécimal (hd)."],
    term:"Tampon de 64 octets, entrée de 80 : les 16 octets excédentaires écrivent sur ce qui suit\n<span class=\"tdim\">La question n’est pas « puis-je déborder ? » mais « que vaut chaque octet, et où tombe-t-il ? »</span>",
    ex:{ type:"qcm", q:"Pourquoi un débordement trop long peut-il faire échouer l’attaque au lieu de la renforcer ?",
      opts:["Parce que le programme devient plus lent", "Parce qu’au-delà de la cible, on écrase les données de contrôle du programme dans un état irrécupérable : le programme plante avant de servir à quoi que ce soit", "Parce que le système efface les longues entrées"], ok:1 },
    why:"Exploiter n’est pas inonder : c’est une écriture de précision dans une mémoire dont on connaît la carte. La version hard de chaque défi ajoute le vrai travail — retrouver cette carte (offsets, tailles) dans le binaire, au débogueur, sans le source." },
  { id:"ICS-26", mod:"Binary Exploitation", t:"Détourner le flux : adresse de retour et PIE", sub:"Écraser l’adresse de retour pour choisir la suite du programme — malgré l’adresse de chargement aléatoire.",
    read:["Le détournement de contrôle (control hijack) vise le morceau le plus précieux de la pile : l’adresse de retour, l’endroit où le programme reviendra quand la fonction se termine. La déborder avec une adresse choisie, c’est décider de la suite du programme — typiquement sauter vers la fonction qui donne le flag. Une variante ajoute un contrôle supplémentaire à contourner avant d’y arriver : un garde-fou conçu pour empêcher exactement ça.",
      "La défense PIE (code indépendant de la position) charge le programme à une adresse aléatoire à chaque lancement : l’adresse de la fonction visée devient inconnue. Mais l’aléa a une limite structurelle : la mémoire se charge par pages de 0x1000 octets, donc les 12 derniers bits des adresses — trois chiffres hexadécimaux — ne changent jamais. Si la fonction visée se trouve à un décalage fixe du début du programme, on peut écraser seulement l’octet faible de l’adresse de retour sauvegardée et prédire partiellement le reste.",
      "Le dernier bloc ajoute un contrôle sur la longueur de l’entrée dans un binaire PIE : il faut connaître les fonctions utilisées par le programme — leurs pages de manuel — pour comprendre ce que le contrôle mesure vraiment, et ce qu’il ne mesure pas."],
    ex:{ type:"qcm", q:"Pourquoi PIE ne rend-il pas l’adresse d’une fonction totalement imprévisible ?",
      opts:["Parce que l’aléa est faible sur les petits programmes", "Parce que le chargement se fait par pages alignées : les 12 bits de poids faible des adresses restent fixes, seul le haut varie", "Parce que PIE est désactivé par défaut"], ok:1 },
    why:"0x1000 = 4096 = 2^12 : l’alignement des pages fige les trois derniers chiffres hexadécimaux de chaque adresse. Un décalage connu depuis le début du programme (0x1337 dans l’exemple du module) permet de reconstruire l’adresse visée à partir d’une fuite partielle — l’aléa protège, mais il a des bords prévisibles." },
  { id:"ICS-27", mod:"Binary Exploitation", t:"Écrire du shellcode : du code en données", sub:"Injecter ses propres instructions et les faire exécuter : NOP sled et octets interdits.",
    read:["Le shellcode est du code machine que l’attaquant fournit comme de simples données, puis fait exécuter : historiquement pour ouvrir un shell, ici pour lire le flag. L’écrire suppose tout ce que Computing 101 a construit : des instructions assembleur, encodées en octets, sans l’aide d’un compilateur pour corriger les détails.",
      "Deux contraintes structurent le module. La NOP sled : une partie de l’entrée est sautée aléatoirement avant l’exécution — on précède le shellcode d’une glissière d’instructions NOP (qui ne font rien) pour que l’atterrissage, où qu’il tombe dans la glissière, glisse jusqu’au vrai code. Et le shellcode sans octet nul : certains canaux d’entrée coupent les données au premier 0x00, il faut donc encoder les mêmes opérations sans jamais produire cet octet.",
      "Ces contraintes sont le cœur du métier : le code ne doit pas seulement être correct, il doit survivre au canal qui le transporte et à l’endroit imprécis où l’exécution commence."],
    ex:{ type:"qcm", q:"À quoi sert une NOP sled devant un shellcode ?",
      opts:["À rendre le shellcode plus rapide", "À absorber l’imprécision du saut : atterrir n’importe où dans la glissière de NOP fait glisser l’exécution jusqu’au shellcode", "À cacher le shellcode des antivirus"], ok:1 },
    why:"L’attaquant connaît rarement l’adresse exacte où son code sera atteint. La NOP sled transforme une cible ponctuelle en zone d’atterrissage : c’est une technique de robustesse, pas de furtivité — elle échange de l’espace contre de la certitude." },
  { id:"ICS-28", mod:"Binary Exploitation", t:"Détourner vers le shellcode : l’exploitation complète", sub:"Assembler les pièces : le débordement choisit l’adresse, le shellcode fait le reste.",
    read:["Les derniers défis rassemblent le module : détourner le flux de contrôle — l’adresse de retour écrasée des leçons précédentes — non plus vers une fonction du programme, mais vers ton propre shellcode. Première forme : le shellcode est mappé en mémoire, entré séparément, et il faut sauter dessus. Deuxième forme, la complète : le shellcode voyage dans l’attaque elle-même, au sein des données du débordement.",
      "Chaque version hard retire les béquilles : pas de sorties de débogage utiles (l’information se récupère au débogueur), pas de source (le binaire se rétro-ingénie en s’aidant de la version easy comme référence), et une randomisation différente — longueurs de tampons et offsets changent, donc rien ne se transpose sans nouvelle mesure.",
      "C’est la forme canonique de l’exploitation binaire classique : une erreur de mémoire donne l’écriture, l’écriture donne le contrôle du pointeur d’instruction, et le contrôle donne l’exécution de code arbitraire. Les défenses modernes — canaris de pile, ASLR, mémoire non exécutable, vues dans le cours du module — existent précisément pour casser un maillon de cette chaîne."],
    ex:{ type:"order", q:"Remets dans l’ordre la chaîne d’une exploitation vers shellcode injecté :",
      items:["Trouver le débordement et mesurer l’offset jusqu’à l’adresse de retour", "Construire l’entrée : remplissage, adresse du shellcode, shellcode", "Le programme copie l’entrée et écrase l’adresse de retour", "Au retour de la fonction, l’exécution saute sur le shellcode", "Le shellcode lit le flag"],
      disp:[2,0,4,1,3] },
    why:"Chaque étape dépend de la précédente : sans l’offset exact, l’adresse écrasée tombe à côté ; sans le contrôle du retour, le shellcode reste des données inertes. Comprendre cette chaîne, c’est comprendre du même coup pourquoi chaque défense moderne vise un maillon précis — canaris contre l’écrasement, NX contre l’exécution, ASLR contre la prédiction d’adresse." },
  { id:"ICS-29", mod:"Integrated Security", t:"Tout ensemble : les défis intégrés", sub:"Crypto + binaire, rétro-ingénierie + binaire, web + binaire : les concepts cessent d’être séparés.",
    read:["Le dernier module est la marche finale vers la ceinture orange : chaque défi combine au moins deux concepts des modules précédents dans un seul problème de bout en bout. Le site ne donne que les concepts utilisés — à toi de trouver comment ils s’emboîtent.",
      "ECB-to-Win et ECB-to-Shellcode marient cryptographie et exploitation binaire : la faiblesse du mode ECB (module Cryptography) devient une pièce d’une attaque contre un programme (module Binary Exploitation) — d’abord pour atteindre la fonction gagnante, puis pour aller jusqu’au shellcode. CIMG Screenshots et sa suite combinent rétro-ingénierie et exploitation : le format cIMG, reconstruit au module précédent, rencontre un programme à exploiter.",
      "Wily Webserver et The Watering Hole, enfin, croisent sécurité web et exploitation binaire : le serveur web n’est plus seulement une application à tromper, c’est un programme mémoire à corrompre. La compétence testée n’est plus aucun des sujets pris séparément : c’est le transfert — reconnaître, dans un problème nouveau, les pièces anciennes qu’il contient."],
    ex:{ type:"qcm", q:"Qu’est-ce que les défis intégrés évaluent de plus que les modules séparés ?",
      opts:["La vitesse de frappe au terminal", "Le transfert : reconnaître dans un problème combiné les concepts appris séparément, et les enchaîner", "La mémorisation des commandes"], ok:1 },
    why:"Les incidents réels ne portent pas d’étiquette de module : un même système y mêle web, crypto et binaire. Savoir chaque technique isolément ne suffit pas — encore faut-il repérer laquelle s’applique, et dans quel ordre. C’est exactement l’esprit d’un poste SOC comme d’un examen : relier les pièces." }
];